import {voyages,drawVoyages,progress} from './voyages.js';
import * as E from './engine.js';
import {playableMap} from './europe-map.js';
import {artFor} from './tile-art.js';
const app=document.querySelector('#app');let mode='tuiles';let drawn=[],pending=null;let g=null,screen='home',bike='gravel',selected=0,zoom=1,modal='',message='',auto=localStorage.getItem('velo-auto')!=='false';
try{g=JSON.parse(localStorage.getItem('velo-save'));if(g?.version!==1)g=null;}catch{}
E.upgradePlateau(g);
const btn=(text,action,cls='')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
function tile(t){const a=artFor(t),c=E.terrains[t.type];if(!a)return `<svg viewBox="0 0 100 100" aria-label="${c.name}"><rect width="100" height="100" fill="${c.color}"/>${E.roads(t).map(d=>`<path d="M50 50 L${[[50,0],[100,50],[50,100],[0,50]][d].join(' ')}" stroke="#e6d5b6" stroke-width="10"/><path d="M50 50 L${[[50,0],[100,50],[50,100],[0,50]][d].join(' ')}" stroke="#92908a" stroke-width="7"/>`).join('')}</svg>`;return `<img class="tile-art" src="${a.src}" alt="${c.name}, ${t.roads.length} sorties" draggable="false" style="transform:rotate(${a.rotation*90}deg)"/>`;}


function artwork(v){return `<div class="voyage-art art-${v.id}" role="img" aria-label="Illustration du voyage ${v.title}"></div>`;}
function card(v){const demo={voyage:v.id,mode,board:{},travel:[]};return `<article class="voyage-choice" style="--voyage-color:${v.color}">${artwork(v).replace('voyage-art art-','voyage-art full-card art-')}<div class="voyage-body"><span class="eyebrow">CARTE VOYAGE</span><h2>${v.title}</h2><p class="route">${v.from} → ${v.to}</p><ul>${progress(demo).rows.map(r=>`<li>${r.target} ${r.label.toLowerCase()}</li>`).join('')}</ul>${v.chains?'<p class="muted">Chaînes séparées par un autre terrain.</p>':''}<button data-voyage="${v.id}">Choisir ce voyage →</button></div></article>`;}
function chooseVoyage(){return `<main class="voyage-selection"><span class="eyebrow">TON PROCHAIN VOYAGE</span><h1>Trois cartes. Une aventure.</h1><p>${mode==='plateau'?'Plateau Europe : départ et arrivée fixés, itinéraire libre.':'Tuiles : construis ton itinéraire.'} Choisis le voyage à réaliser. Ta carte et ses compteurs restent visibles pendant la partie.</p><div class="voyage-grid">${drawn.map(card).join('')}</div></main>`;}
function objective(){const p=progress(g);if(!p)return '';return `<section class="objective" style="--voyage-color:${p.v.color}" aria-label="Votre carte Voyage">${artwork(p.v)}<div class="objective-title"><span class="eyebrow">CARTE VOYAGE</span><h3>${p.v.title}</h3><strong>${p.v.from} → ${p.v.to}</strong><small>${p.ready?'Étapes validées : rejoins '+p.v.to+'.':'Parcours les étapes, puis rejoins '+p.v.to+'.'}</small></div><div class="objective-checks">${p.rows.map(r=>`<div class="${r.done?'checked':''}">${r.done?'✓':'○'} ${r.label} <b>${r.value}/${r.target}</b></div>`).join('')}<div class="${p.won?'checked':''}">${p.won?'✓':'○'} Arrivée à ${p.v.to}</div></div></section>`;}

function save(){if(g&&auto)try{localStorage.setItem('velo-save',JSON.stringify(g));}catch{message='La sauvegarde est indisponible dans ce navigateur.';}}
function render(){let scroll=document.querySelector('.map'),sx=scroll?.scrollLeft,sy=scroll?.scrollTop;app.innerHTML=`<header><b>🚲 L’Aventure à Vélo</b><div>${btn('Règles','rules','light')} ${screen==='game'?btn('☰','home','light'):''}</div></header>`+(screen==='voyages'?chooseVoyage():screen==='game'&&g?game():home())+overlay();bind();if(scroll){let m=document.querySelector('.map');if(m){m.scrollLeft=sx;m.scrollTop=sy;}}save();}
function home(){return `<main class="home"><section><div class="eyebrow">EXPLORATION • STRATÉGIE • LIBERTÉ</div><h1>Deux façons<br>de vivre<br>l’aventure.</h1><p class="sub">Explore le plateau de l’Europe ou construis ton itinéraire avec les tuiles.</p>${screen==='modes'?modeChoices():screen==='select'?`<p class="mode-label">${mode==='plateau'?'🗺 Plateau Europe':'🧩 Tuiles'} · ${btn('Changer','modes','light')}</p><div class="choices"><div class="choice ${bike==='gravel'?'selected':''}" data-bike="gravel"><h3>🚴 Gravel</h3><p>Montagnes et cols : coût réduit de 1 énergie.</p></div><div class="choice ${bike==='randonneur'?'selected':''}" data-bike="randonneur"><h3>🚲 Randonneur</h3><p>Départ avec 5 provisions au lieu de 3.</p></div></div>${btn('Commencer le voyage →','start')}`:`${btn('Nouvelle aventure →','new')} ${g?btn('Reprendre','continue','light'):''}<p style="margin-top:14px">${btn('Paramètres','settings','light')}</p>`}<p class="footer">SOLO • PLATEAU OU TUILES • SAUVEGARDE SUR CET APPAREIL</p></section><div class="hero"><span class="sun">☀️</span><span>🚴</span></div></main>`;}
function game(){if(g.mode==='plateau')return plateauGame();E.rescueHand(g);let tiles=Object.values(g.board),s=g.phase==='place'&&g.hand[selected]?E.spots(g,g.hand[selected]):[],all=[...tiles,...s],minX=Math.min(...all.map(t=>t.x))-1,minY=Math.min(...all.map(t=>t.y))-1,maxX=Math.max(...all.map(t=>t.x))+1,maxY=Math.max(...all.map(t=>t.y))+1,size=132*zoom,reachable=E.moves(g);return `<main class="game"><div class="topbar"><div><span class="eyebrow">CARNET DE VOYAGE</span><h2 style="margin:5px 0">Étape ${g.turn} <small class="muted">${tiles.length}/48 tuiles</small></h2></div><div class="stats">${[['⚡','Énergie',g.energy+'/10'],['🍎','Provisions',g.food],['🪙','Argent',g.money],['✨','Aventure',g.points]].map(([i,n,v])=>`<div class="stat">${i} ${n}<strong>${v}</strong></div>`).join('')}</div></div><div class="hint">${g.done?'Votre voyage est terminé.':g.phase==='place'?'1 · Choisis une tuile, tourne-la et touche un emplacement +.':g.phase==='move'?(!g.hand.length?'Le plateau est complet : continue à rouler vers ton objectif.':'2 · Touche une tuile voisine dorée pour rouler.'):'3 · Une rencontre vous attend.'}</div>${objective()}<div class="layout"><section><div class="map-wrap"><div class="map"><div class="world" style="width:${(maxX-minX+1)*size}px;height:${(maxY-minY+1)*size}px">${tiles.map(t=>`<div class="tile ${g.phase==='move'&&reachable.includes(t)?'reachable':''}" data-move="${E.key(t.x,t.y)}" style="left:${(t.x-minX)*size}px;top:${(t.y-minY)*size}px;width:${132*zoom}px;height:${132*zoom}px">${tile(t)}<label>${t.name||E.terrains[t.type].name}</label>${g.pos===E.key(t.x,t.y)?'<span class="rider">🚴</span>':''}</div>`).join('')}${s.map(t=>`<button class="spot" data-place="${t.x},${t.y}" style="left:${(t.x-minX)*size}px;top:${(t.y-minY)*size}px;width:${132*zoom}px;height:${132*zoom}px">+</button>`).join('')}</div></div><div class="maptools">${btn('−','zoomout')}${btn('+','zoomin')}${btn('◎','center')}</div></div><div class="hand">${g.hand.map((t,i)=>`<button data-select="${i}" class="${i===selected?'active':''}" ${g.phase!=='place'?'disabled':''}>${tile(t)}<small>${E.terrains[t.type].name}</small></button>`).join('')}${btn('↻ Tourner','rotate','light')}</div><div class="toast" role="status">${message}</div></section>${sidebar()}</div></main>`;}
function overlay(){let content='';if(g?.event&&screen==='game')content=`<span class="event-icon">${E.terrains[g.board[g.pos].type].icon}</span><span class="eyebrow">CARTE AVENTURE</span><h2>${g.event.title}</h2><p>${g.event.text}</p><p>${g.items.includes(g.event.protect)?'Votre équipement annule la pénalité.':Object.entries(g.event.effect).map(([k,v])=>`${v>0?'+':''}${v} ${{energy:'énergie',food:'provision',money:'argent',points:'points Aventure'}[k]}`).join(' · ')}</p>${btn('Reprendre la route →','resolve')}`;else if(g?.done&&screen==='game')content=`<span class="event-icon">🏆</span><h2>${g.voyageWon?"Voyage accompli !":"Un voyage à raconter."}</h2>${g.voyage?`<p>${progress(g).v.from} → ${progress(g).v.to} · ${g.voyageWon?"Toutes les étapes sont validées.":"Objectif non terminé."}</p>`:""}<h1>${E.score(g)} <small style="font-size:20px">points</small></h1><p>${g.points} points Aventure · ${g.discoveries} découvertes · ${g.cols} cols · ${g.cities} villes · ${g.visited.length-1} étapes inédites.</p><p class="muted">Score = Aventure + découvertes × 3 + cols × 2 + villes + étapes inédites. ${g.steps} déplacements effectués.</p>${btn('Retour à l’accueil','home')}`;else if(modal==='rules')content=`<h2>Prendre la route</h2><p><b>Deux versions :</b> en mode Tuiles, construis le réseau ; en mode Plateau Europe, pars de la ville de ta carte Voyage et choisis librement les cases terrestres voisines. Aucun itinéraire ni ordre de villes ne sont imposés. Les cases dorées indiquent les déplacements possibles, une case par étape. Les pointillés représentent des liaisons en ferry. La carte est une représentation simplifiée, pas une carte de navigation.</p><p>Pose une tuile à chaque tour. Chaque route rejoint le milieu d’un côté. Les routes doivent correspondre à tous les voisins ; deux côtés sans route peuvent aussi se toucher. Tourne ta tuile pour trouver un passage.</p><p>Déplace-toi ensuite d’une seule case par une route connectée, ou termine l’étape sur place. Plaine, ville et côte coûtent 1 énergie ; montagne 2 ; col 3. Le gravel réduit les coûts en montagne de 1.</p><p>Mange ou bivouaque pour récupérer. En ville, achète des provisions, travaille ou équipe ton vélo. Les pauses et services sont libres dans ce prototype.</p><p>Chaque lieu rapporte des points une seule fois. Les événements concernent uniquement les premières visites. Au départ, tire trois cartes Voyage et choisis-en une. Visite les terrains et villes demandés, puis rejoins la ville d’arrivée nommée sur une tuile. Départ et arrivée ne comptent pas parmi les villes intermédiaires. Une tuile ne compte qu’une fois ; revenir sur une tuile interrompt une série. Les deux chaînes du Nord doivent être séparées par un autre terrain. Une fois les 48 tuiles posées, tu peux continuer à rouler pour finir ton objectif.</p><p>Fais glisser la carte pour l’explorer. Les boutons + et − règlent le zoom. Une main bloquée reçoit une tuile de secours adaptée au réseau.</p>${btn('C’est parti','close')}`;else if(modal==='settings')content=`<h2>Paramètres</h2><p>Sauvegarde automatique : ${auto?'activée':'désactivée'}</p>${btn('Activer / désactiver','autosave')}<p class="muted">La partie reste sur ce navigateur. Pour jouer hors connexion, ouvre d’abord le jeu en ligne et installe-le depuis le menu du navigateur Android.</p>${btn('Fermer','close','light')}`;else if(modal==='confirm')content=`<h2>Nouvelle aventure ?</h2><p>La sauvegarde actuelle sera remplacée lorsque tu commenceras.</p>${btn('Choisir une version','selectbike')} ${btn('Annuler','close','light')}`;else if(modal==='finish')content=`<h2>Terminer ce voyage ?</h2><p>Ton score sera calculé avec les découvertes déjà réalisées.</p>${btn('Voir mon score','end')} ${btn('Continuer','close','light')}`;else if(modal==='shop')content=`<h2>Équiper son vélo</h2><div class="shop">${Object.entries(E.equipment).map(([id,e])=>`<button data-buy="${id}" ${g.items.includes(id)||g.money<e.cost?'disabled':''}>${e.name} · ${e.cost} pièces<br><small>${e.desc}${g.items.includes(id)?' · acquis':''}</small></button>`).join('')}</div>${btn('Fermer','close','light')}`;return content?`<div class="modal-back"><section class="modal" role="dialog" aria-modal="true">${content}</section></div>`:'';}
function bind(){document.querySelectorAll('[data-voyage]').forEach(el=>el.onclick=()=>{const id=el.dataset.voyage;if(!drawn.some(v=>v.id===id))return;g=E.makeGame(bike,pending.seed,id,mode);zoom=1;pending=null;screen='game';render();center();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>act(el.dataset.action));document.querySelectorAll('[data-mode]').forEach(el=>el.onclick=()=>{mode=el.dataset.mode;screen='select';render();});document.querySelectorAll('[data-bike]').forEach(el=>el.onclick=()=>{bike=el.dataset.bike;render();});document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>{selected=+el.dataset.select;render();});document.querySelectorAll('[data-place]').forEach(el=>el.onclick=()=>{let [x,y]=el.dataset.place.split(',').map(Number);E.place(g,selected,x,y);selected=0;message='Tuile posée. À toi de choisir ton étape.';render();});document.querySelectorAll('[data-move]').forEach(el=>{el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.onclick();}};el.onclick=()=>{if(g.phase!=='move')return;if(!E.move(g,el.dataset.move))message='Route inaccessible ou énergie insuffisante. Une pause peut aider.';else message='';render();};});document.querySelectorAll('[data-buy]').forEach(el=>el.onclick=()=>{E.buy(g,el.dataset.buy);render();});}
function center(){document.querySelector('.rider')?.parentElement.scrollIntoView({block:'center',inline:'center',behavior:'smooth'});}
function act(a){message='';if(a==='new'){if(g&&!g.done)modal='confirm';else screen='modes';}else if(a==='selectbike'){screen='modes';modal='';}else if(a==='modes')screen='modes';else if(a==='start'){pending=E.makeGame(bike);drawn=drawVoyages(()=>E.random(pending));screen='voyages';selected=0;}else if(a==='continue')screen='game';else if(a==='home'){screen='home';modal='';}else if(['rules','settings','shop','finish'].includes(a))modal=a;else if(a==='close')modal='';else if(a==='end'){g.done=true;modal='';}else if(a==='autosave'){auto=!auto;localStorage.setItem('velo-auto',auto);}else if(a==='rotate'&&g.phase==='place'){let t=g.hand[selected];if(t)t.rotation=(t.rotation+1)%4;}else if(a==='resolve')E.resolve(g);else if(a==='skip'&&g.phase==='move')E.endTurn(g);else if(['eat','rest','work','food','sleep','restaurant'].includes(a)){if(!E.recover(g,a))message='Cette action n’est pas disponible avec tes ressources actuelles.';}else if(a==='zoomin')zoom=Math.min(1.6,zoom+.2);else if(a==='zoomout')zoom=Math.max(.6,zoom-.2);render();if(['start','continue','center'].includes(a))center();}
render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});

function sidebar(){return `<aside class="panel"><h3>La pause du cycliste</h3><p class="muted">${g.board[g.pos].name||E.terrains[g.board[g.pos].type].name} · ${g.bike==='gravel'?'Gravel':'Randonneur'}</p><div class="actions">${btn('🍎 Manger · +'+(g.items.includes('rechaud')?5:3)+' énergie','eat')}${btn('⛺ Bivouac · +'+(g.items.includes('tente')?4:2),'rest')}${g.board[g.pos].type==='ville'?btn('🥕 Épicerie · 2 provisions / 1 pièce','food')+btn('🍽 Restaurant · +4 énergie / 1 pièce','restaurant')+btn('🔧 Travailler · +2 pièces','work')+btn('🚲 Boutique vélo · équipements','shop'):''}${['ville','camping','auberge'].includes(g.board[g.pos].type)?btn('🛏 Auberge · dormir / 1 pièce','sleep'):''}${btn('Finir l’étape sans rouler','skip')}${btn('Terminer le voyage','finish')}</div><h4>Journal de route</h4><div class="log">${g.log.map(l=>`<div>• ${l}</div>`).join('')}</div><p class="muted">${g.visited.length-1} nouvelles étapes · ${g.cols} cols<br>${g.items.map(i=>E.equipment[i].name).join(' · ')||'Aucun équipement'}</p></aside>`;}

function modeChoices(){return `<div class="mode-choices"><button class="mode-card" data-mode="plateau"><img src="assets/europe/board.webp" alt="Carte illustrée de l’Europe avec plaines, montagnes, côtes et villes"/><div><span class="eyebrow">CARTE FIXE</span><h3>🗺 Plateau Europe</h3><p>Voyage de ville en ville sur une carte illustrée. Choisis tes passages entre plaines, montagnes et littoraux.</p><strong>Explorer l’Europe →</strong></div></button><button class="mode-card" data-mode="tuiles"><img src="assets/tiles/plaine-0.webp" alt="Tuile illustrée avec routes"/><div><span class="eyebrow">ITINÉRAIRE À CONSTRUIRE</span><h3>🧩 Tuiles</h3><p>Pose et tourne les tuiles pour créer ton propre voyage. Retrouve la version actuelle et ses 48 tuiles.</p><strong>Construire mon parcours →</strong></div></button></div>`;}
function plateauGame(){
 const nodes=Object.values(g.board),reachable=E.moves(g),scale=.8*zoom,current=g.board[g.pos];
 return `<main class="game"><div class="topbar"><div><span class="eyebrow">PLATEAU EUROPE</span><h2 style="margin:5px 0">Étape ${g.turn} <small class="muted">${current.name||E.terrains[current.type].name}</small></h2></div><div class="stats">${[['⚡','Énergie',g.energy+'/10'],['🍎','Provisions',g.food],['🪙','Argent',g.money],['✨','Aventure',g.points]].map(([i,n,v])=>`<div class="stat">${i} ${n}<strong>${v}</strong></div>`).join('')}</div></div><div class="hint">${g.done?'Votre voyage est terminé.':g.phase==='event'?'Une rencontre vous attend.':'Itinéraire libre : choisis une case voisine dorée, dans la direction de ton choix. 🏁 indique ton arrivée.'}</div>${objective()}<div class="layout"><section><div class="map-wrap"><div class="map"><div class="europe-world" style="width:${1536*scale}px;height:${1024*scale}px">${playableMap(g,reachable,E.cost)}</div></div><div class="maptools">${btn('−','zoomout')}${btn('+','zoomin')}${btn('◎','center')}</div></div><div class="board-legend">${['plaine','montagne','ville','cote'].map(type=>`<span>${E.terrains[type].icon} ${E.terrains[type].name}</span>`).join('')}<span>🚩 Départ</span><span>🏁 Arrivée</span><span>🟨 Contours dorés : accessibles</span><span>┄ Ferry</span></div><p class="muted">${nodes.length} cases jouables · relief et trajets simplifiés pour le jeu · une case par étape. Choisis librement tes directions et tes détours entre cases voisines. Le paysage reste visible au repos ; les contours dorés indiquent les déplacements possibles. Les pointillés indiquent uniquement les ferries.</p><div class="toast" role="status">${message}</div></section>${sidebar()}</div></main>`;
}
